(* [comment removed for export] *)
Definition ret_kind (ks : list kind) (rt : nat * nat * nat * Z) : kind :=
  let '(j, s, _, pc) := rt in
  if Z.eqb pc SCANEXP then (match reg_e (nth j CPS CA.dummy_cp) 10 with ELit _ => KRXa | _ => KPost end) else nth s ks KDead.
Definition kinds : list kind := ltac2:(Rpl.RP.run_i (rplG ()) 0 "S20!1+1+2!2+3!2+3!2+3+4+4+4+5!5'001$ks;R0$rt;R1!3'6+2#2!3,7+2!2'8#2#1!1,9+2/RETS;/DKINDS;").
Definition kind_of (i : nat) : kind := ltac2:(Rpl.RP.run_i (rplG ()) 1 "S00$i;R+4!4':+2#1';,<").

Definition FOOT : list SGP.region := ltac2:(Rpl.RP.run_i (rplG ()) 0 "S60!2+3+=+5!2+30+=}2|30;!1,B3|20;!3,71!4,>0+=!4,>+=+5!1,?2!1,@|800;!1,A!1,B|=01e0;!3,71!4,>0+=!4,>+=+5!1,?}E4!1,A4!3,71!4,>0+=!4,>+=+5!1,A,C/ERRNO;!1,A!1,B5!1,91").
Definition FOOT2 : list SGP.region := ltac2:(Rpl.RP.run_i (rplG ()) 0 "S30!2+3+=+5!2+30+=|20;!3,71!4,>0+=!4,>+=+5!1,?}2!1,@|800;!1,A!1,B|=01e0;!3,71!4,>0+=!4,>+=+5!1,A,C/ERRNO;!1,A!1,B2!1,91").
(* [comment removed for export] *)
Definition F0x : list SGP.region := [(EVar 2, -256, ELit 256); (EVar 2, 0, ELit 8416); (EVar 21, 8, ELit 8); (ELit 0, ERRNO, ELit 4)].

(* [comment removed for export] *)
(* [comment removed for export] *)
Definition rng_in (kn : list kentry) (e : expr) (lo hi : Z) : bool :=
  existsb (fun K => match K with KRange e' l h => (expr_eqb e' e && Z.leb lo l && Z.leb h hi)%bool | _ => false end) kn.
Definition cls_chk (cl : cls) (c : CC.cutpoint) (cv : expr) : bool := ltac2:(Rpl.RP.run_i (rplG ()) 3 "S30!1,B|50e;!4'I#1#200!2'J!2'J!4'I#1#2,C!1,B|77f;!2'K#1!3,L!1'M#2,C,C!2'K#1!3,L!1'N#2,C,C$cl;R+D$c;R+E$cv;R+=&kn;R!1'F#2!1+1+G-DRN$cl;R+D+H#45!4'I#1#2!1,B|510;!1,B|519;12!2'J2!2'K#1!3,L!1'O#2,C,C1").
(* [comment removed for export] *)
Definition lit_or_fact (c : CC.cutpoint) (z : Z) : bool := (expr_eqb (reg_e c 20) (ELit z) || has (CC.cp_know c) (KRange (reg_e c 20) z z))%bool.
Definition sc_chk (f : flg) (cl : cls) (c : CC.cutpoint) : bool := ltac2:(Rpl.RP.run_i (rplG ()) 3 "S90}^3!1'R#2}8}:!1,?0}1!1,?#1!1,B,^1}D$f;R+P$cl;R+D$c;R+E&kn;R!1'F#1!1+1+G!2'J!2'J!2'J!2'J!2'J!2'Q01!2'K#1!3,S'T2'U!2'K#1!3,L'V,C!2'W!1,B|20;'X-=RN$x;R+=+H!2'Y#238$z;R+5-5RN$z;R+5+H#13!2'J!2'K#2!3,L4,C,C-DRN$cl;R+D+H#45,Z,Z,[,[,Z$p;R+\,Z$p;R+\,Z$cv;R+4!2'J!2'J!2'K#2!3,S'^056!2'K#2!3,L47'X!3'^2#4#36$op;R+^3$a;R+=$b;R+=,Z$op;R+^3$a;R+=$b;R+=,Z$op;R+^4$a;R+=$b;R+=,Z$op;R+^4$a;R+=$b;R+=,Z$sx;R+H$lo;R+4$n;R+4$e;R+=,Z$sx;R+H$k;R+4$i;R+5$n;R+4,Z-PRN$f;R+P+H#43,[,[!2'^51!2'Y#28-DRN$cl;R+D+H#35,[-PRN$f;R+P+H#43,[,[!2'^6#2,C,[,[-PRN$f;R+P+H#43,Z,Z!2'^6#27").
Definition cut_chk (i : nat) (c : CC.cutpoint) : bool := ltac2:(Rpl.RP.run_i (rplG ()) 2 "S20!1'^;#1!2'^:0'^=$i;R+4$c;R+E!2'J!2'J!2'^7'^8!1'R#1!2'^9!2'^:0'^<1-2RN$x;R+2+H!1'^>#25,[$f;R+P$cl;R+D!3'^?#2#1#3-^@RN$x;R!1+^@+=+H!1'^A!1'F#12$v;R+=!2'^5!1'R#2#1,Z1,Z").

(* [comment removed for export] *)
Definition is_lit (e : expr) (z : Z) : bool := expr_eqb e (ELit z).
(* [comment removed for export] *)
Definition flag_rel (srcf : option flg) (cl : cls) (c : CC.cutpoint) (f' : flg) (e20' : expr) : bool :=
  let src_false := match srcf with None | Some G0 => true | Some G1 => false | Some GS4 => lit_or_fact c 0 end in
  let src_true := match srcf with Some G1 => true | Some GS4 => lit_or_fact c 1 | _ => false end in
  let tgt_false := match f' with G0 => true | G1 => false | GS4 => is_lit e20' 0 end in
  let tgt_true := match f' with G1 => true | G0 => false | GS4 => is_lit e20' 1 end in
  let same := match srcf, f' with Some GS4, GS4 => (expr_eqb e20' (reg_e c 20) && APC.expr_vars_lt (CC.cp_nx c) (reg_e c 20))%bool | _, _ => false end in
  match cl with
  | CDig => ((src_false && tgt_false) || (src_true && tgt_true) || same)%bool
  | CDot => (src_false && tgt_true)%bool
  | _ => false
  end.
Definition cell_dec (c : CC.cutpoint) (ps : SR.post_spec) : bool := ltac2:(Rpl.RP.run_i (rplG ()) 2 "S00$c;R+E$ps;R+^B-^@RN$x;R!1+^@+=+H!1'^A!1'F#22$vs;R+=-^@RN$x;R!1+^@+=+H!1'^A!1'^C#22$vl;R+=!2'J!2'^D#1!2'^E#2!1,@,^1!2'^5!1'R#4#2,Z,Z").
Definition goto_chk2 (i : nat) (c : CC.cutpoint) (ps : SR.post_spec) (j : nat) (cj : CC.cutpoint) (s : CC.subst) : bool :=
  let k' := CC.slook s 48 in
  let e20' := CC.esubstL NF s (reg_e cj 20) in
  match kind_of i with
  | KEnt => match kind_of j with
            | KEnt => true
            | KSc f' _ => ((expr_eqb k' (APC.eaddz (EVar 47) (-1)) && flag_rel None CDig c f' e20')                                     (* [comment removed for export] *)
                           || (expr_eqb k' (EVar 47) && match f' with GS4 => is_lit e20' 0 | G0 => true | G1 => false end))%bool        (* [comment removed for export] *)
            | _ => false
